// SetRange sets a range filter on a field
// Usage:
//
//	SetRange("No", "10000") - exact match (No = "10000")
//	SetRange("No", "10000", "20000") - range (No between "10000" and "20000")
//	SetRange("No") - removes the filter on the field
func (t *JobQueueEntry) SetRange(fieldName string, values ...interface{}) {
	if t.filters == nil {
		t.filters = make(map[string]*jobQueueEntryFilterCondition)
	}

	var minValue, maxValue interface{}

	switch len(values) {
	case 0:
		if column, ok := t.columnName(fieldName); ok {
			delete(t.filters, column)
		}
		delete(t.filters, fieldName)
		return
	case 1:
		// Exact match: SetRange("No", "10000")
		minValue = values[0]
		maxValue = values[0]
	case 2:
		// Range: SetRange("No", "10000", "20000")
		minValue = values[0]
		maxValue = values[1]
	default:
		fmt.Printf("Error: SetRange requires 1 or 2 values, got %d\n", len(values))
		return
	}

	column, ok := t.columnName(fieldName)
	if !ok {
		// Unknown field: fail closed (no rows) rather than drop the filter or put
		// the name into SQL
		fmt.Printf("Error: SetRange on unknown field %q of Job_Queue_Entry\n", fieldName)
		t.filters[fieldName] = &jobQueueEntryFilterCondition{invalidField: true}
		return
	}

	t.filters[column] = &jobQueueEntryFilterCondition{
		fieldName: column,
		minValue:  minValue,
		maxValue:  maxValue,
	}
}

